begin;
create table public.arena_card_fragments(user_id uuid not null references public.profiles(id)on delete cascade,card_id text not null,quantity integer not null default 0 check(quantity>=0),primary key(user_id,card_id));create table public.arena_alliance_card_requests(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id)on delete cascade,requester_id uuid not null references public.profiles(id)on delete cascade,card_id text not null,requested integer not null check(requested between 1 and 20),received integer not null default 0 check(received>=0),status text not null default'active'check(status in('active','completed','cancelled')),created_at timestamptz not null default now());create table public.arena_alliance_card_donations(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.arena_alliance_card_requests(id)on delete cascade,donor_id uuid not null references public.profiles(id)on delete cascade,amount integer not null check(amount between 1 and 5),created_at timestamptz not null default now());create unique index arena_one_active_card_request on public.arena_alliance_card_requests(requester_id)where status='active';alter table public.arena_card_fragments enable row level security;alter table public.arena_alliance_card_requests enable row level security;alter table public.arena_alliance_card_donations enable row level security;revoke all on public.arena_card_fragments,public.arena_alliance_card_requests,public.arena_alliance_card_donations from anon,authenticated;
create or replace function public.arena_get_alliance_card_requests()returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;insert into public.arena_card_fragments values(v_user,'davi-jovem',10),(v_user,'soldado-de-israel',10),(v_user,'arqueira-da-fe',10)on conflict do nothing;return jsonb_build_object('fragments',(select jsonb_object_agg(card_id,quantity)from public.arena_card_fragments where user_id=v_user),'requests',(select coalesce(jsonb_agg(to_jsonb(x)order by created_at desc),'[]'::jsonb)from(select r.id,r.card_id,r.requested,r.received,r.requester_id,coalesce(p.display_name,'Guardião')requester_name,r.created_at from public.arena_alliance_card_requests r left join public.profiles p on p.id=r.requester_id where r.alliance_id=v_alliance and r.status='active')x));end;$$;
create or replace function public.arena_request_alliance_card(p_card_id text,p_amount integer)returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_id uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null or p_card_id!~'^[a-z0-9-]{3,60}$'then raise exception'invalid request';end if;insert into public.arena_alliance_card_requests(alliance_id,requester_id,card_id,requested)values(v_alliance,v_user,p_card_id,p_amount)returning id into v_id;return v_id;end;$$;
create or replace function public.arena_donate_alliance_card(p_request_id uuid,p_amount integer)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_request public.arena_alliance_card_requests%rowtype;v_balance integer;v_amount integer;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;select*into v_request from public.arena_alliance_card_requests where id=p_request_id and alliance_id=v_alliance and status='active'for update;if not found or v_request.requester_id=v_user then raise exception'request unavailable';end if;select quantity into v_balance from public.arena_card_fragments where user_id=v_user and card_id=v_request.card_id for update;v_amount:=least(p_amount,v_request.requested-v_request.received);if v_amount not between 1 and 5 or coalesce(v_balance,0)<v_amount then raise exception'insufficient fragments';end if;update public.arena_card_fragments set quantity=quantity-v_amount where user_id=v_user and card_id=v_request.card_id;insert into public.arena_card_fragments values(v_request.requester_id,v_request.card_id,v_amount)on conflict(user_id,card_id)do update set quantity=public.arena_card_fragments.quantity+v_amount;update public.arena_alliance_card_requests set received=received+v_amount,status=case when received+v_amount>=requested then'completed'else'active'end where id=v_request.id;insert into public.arena_alliance_card_donations(request_id,donor_id,amount)values(v_request.id,v_user,v_amount);update public.arena_alliance_members set contribution=contribution+v_amount*2 where alliance_id=v_alliance and user_id=v_user;return jsonb_build_object('donated',true,'amount',v_amount);end;$$;
revoke all on function public.arena_get_alliance_card_requests(),public.arena_request_alliance_card(text,integer),public.arena_donate_alliance_card(uuid,integer)from public;grant execute on function public.arena_get_alliance_card_requests(),public.arena_request_alliance_card(text,integer),public.arena_donate_alliance_card(uuid,integer)to authenticated;commit;
